use super::{assert_close, check_fixed, check_fixed_rescale, F32_TOL, F64_TOL, ROUND_TRIP_TOL};
use unitsnet_rs::*;

#[test]
fn steradians() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x;
        assert_close(SolidAngle::from_steradians(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = x;
        assert_close(SolidAngle::from_base(base).as_steradians(), back, F64_TOL);
        assert_close(
            SolidAngle::from_steradians(v).as_steradians(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            SolidAngle::from_steradians(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            SolidAngle::from_base(base as f32).as_steradians() as f64,
            back,
            F32_TOL,
        );
    }
}

